import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"研究协作系统","description":"项目契约：使用多 Agent 完成长时研究任务，并验证角色边界、共享状态、引用、预算和终止条件。","frontmatter":{"title":"研究协作系统","description":"项目契约：使用多 Agent 完成长时研究任务，并验证角色边界、共享状态、引用、预算和终止条件。","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"py-agent/architecture/projects/research-collaboration-system.md","filePath":"py-agent/architecture/projects/research-collaboration-system.md","lastUpdated":null}'),l={name:"py-agent/architecture/projects/research-collaboration-system.md"};function i(n,e,s,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="研究协作系统" tabindex="-1">研究协作系统 <a class="header-anchor" href="#研究协作系统" aria-label="Permalink to &quot;研究协作系统&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本项目类型为 <strong>多 Agent 系统</strong>，也是项目实战的综合项目。只有在规划、取证、写作和审校确实需要独立上下文与并行执行时才拆分角色，并用单 Agent 基线验证这种复杂度是否值得。</p><h2 id="项目结果" tabindex="-1">项目结果 <a class="header-anchor" href="#项目结果" aria-label="Permalink to &quot;项目结果&quot;">​</a></h2><p>读者最终会得到一个异步研究服务：提交主题和约束后，系统生成研究计划，并行检索与筛选来源，按章节写作，由审校角色检查事实、引用和覆盖率，最终交付带证据清单的 Markdown 报告。</p><h2 id="实现范围" tabindex="-1">实现范围 <a class="header-anchor" href="#实现范围" aria-label="Permalink to &quot;实现范围&quot;">​</a></h2><ul><li>LangGraph 组织 Planner、Researcher、Writer 和 Reviewer 子图；</li><li>共享状态只保存任务、证据、产物引用和预算，不共享无限对话历史；</li><li>搜索与页面读取通过可替换工具适配器接入；</li><li>FastAPI、后台任务和 PostgreSQL 管理长任务、事件流与产物；</li><li>每个角色拥有独立输入契约、工具权限、重试和终止条件；</li><li>引用校验器保证报告引用来自本次已保存证据；</li><li>测试比较单 Agent 与多 Agent 的质量、成本、延迟和失败恢复。</li></ul><h2 id="验收基线" tabindex="-1">验收基线 <a class="header-anchor" href="#验收基线" aria-label="Permalink to &quot;验收基线&quot;">​</a></h2><p>项目必须输出完整执行轨迹，证明循环有上限、并行结果能确定合并、单个角色失败可以恢复，并用实际评测解释采用多 Agent 的收益。浏览器自动操作和开放式代码执行不属于第一版范围。</p>',9)])])}const _=a(l,[["render",i]]);export{u as __pageData,_ as default};
